def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = ''
    for char in message:
        if char.isalpha():
            if char in vowels:
                if char.islower():
                    encoded_message += chr(ord(char) + 2 - 96)
                else:
                    encoded_message += chr(ord(char) + 2 - 64)
            else:
                encoded_message += char.swapcase()
        else:
            encoded_message += char
    return encoded_message
